      "A Constituição Federal de 1988 é classificada, quanto à forma, como escrita (positivada em um texto único) e, quanto ao modo de elaboração, como dogmática (elaborada por um órgão constituinte, sistematizando princípios e ideias vigentes no momento). Quanto à origem, é promulgada (fruto de assembleia constituinte eleita para esse fim, com legitimidade democrática).",
      "Quanto à estabilidade, é rígida — exige processo legislativo mais dificultoso para sua alteração (emenda constitucional) do que o exigido para leis ordinárias, o que garante a supremacia constitucional: todas as demais normas do ordenamento jurídico devem estar em conformidade com a Constituição, sob pena de inconstitucionalidade.",
      "Poder constituinte originário é o poder que cria uma nova Constituição, rompendo com a ordem jurídica anterior — é inicial, ilimitado juridicamente, autônomo e incondicionado. Poder constituinte derivado é o poder de alterar a Constituição já existente (reformador, via emendas) ou de elaborar as constituições estaduais (decorrente) — ambos são limitados, condicionados e subordinados ao poder originário, respeitando as chamadas cláusulas pétreas."
