      "Casa é inviolável; à noite, só entra sem consentimento em flagrante, desastre ou para socorro (nem com ordem judicial fora dessas hipóteses).",
      "Sigilo de comunicação telefônica pode ser quebrado por ordem judicial para investigação criminal — a única exceção expressa do inciso XII."
