        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Direitos e garantias fundamentais: direitos individuais\", a ideia principal é: O art. 5º da Constituição, com seus mais de 78 incisos, é um dos pontos mais cobrados em qualquer concurso — especialmente em provas policiais, pela ligação direta com a atividade de abordagem, busca e apreensão. Para estudar sem travar, guarde primeiro estas palavras-chave: inviolabilidade de domicílio, sigilo de correspondência, devido processo legal. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: À noite, só entra em domicílio sem consentimento por flagrante, desastre ou socorro — mandado judicial só vale para entrada durante o dia.",
