    "corpo": [
      "Remédios constitucionais são ações destinadas a proteger direitos fundamentais específicos, ajuizáveis pelo cidadão diretamente contra atos que os violem. Habeas corpus protege a liberdade de locomoção, sempre que alguém sofrer ou se achar ameaçado de sofrer violência ou coação em sua liberdade de ir e vir, por ilegalidade ou abuso de poder — é gratuito e não exige advogado.",
      "Mandado de segurança protege direito líquido e certo, não amparado por habeas corpus ou habeas data, sempre que violado ou ameaçado por ato de autoridade pública (ou agente de pessoa jurídica no exercício de atribuições do poder público). 'Líquido e certo' significa que os fatos precisam ser comprováveis de plano, por prova documental, sem necessidade de dilação probatória.",
      "Habeas data assegura o conhecimento ou a retificação de informações relativas à pessoa do impetrante, constantes de registros ou bancos de dados de entidades governamentais ou de caráter público. Mandado de injunção é cabível quando a falta de norma regulamentadora torna inviável o exercício de direitos e liberdades constitucionais e das prerrogativas de nacionalidade, soberania e cidadania. Ação popular permite a qualquer cidadão anular ato lesivo ao patrimônio público, à moralidade administrativa, ao meio ambiente e ao patrimônio histórico e cultural."
    ],
