    "corpo": [
      "Direitos sociais são direitos fundamentais de segunda geração (ou dimensão): diferente dos direitos individuais de primeira geração, que exigem abstenção do Estado (não fazer), os direitos sociais exigem uma prestação positiva do Estado (fazer) — políticas públicas, serviços, estruturas que garantam condições mínimas de vida digna.",
      "O art. 6º da Constituição, com redação atualizada por diversas emendas constitucionais ao longo dos anos, lista: educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência social, proteção à maternidade e à infância, e assistência aos desamparados. Repare que 'segurança' aqui aparece tanto como direito individual (art. 5º, caput) quanto como direito social (art. 6º) — a segurança pública, especificamente, tem tratamento próprio no art. 144.",
      "Diferente dos direitos individuais, os direitos sociais frequentemente dependem de regulamentação infraconstitucional e de disponibilidade orçamentária para sua efetivação plena — mas a jurisprudência do STF tem reconhecido a exigibilidade do chamado 'mínimo existencial', um núcleo de prestações essenciais que não pode ser condicionado à disponibilidade financeira do Estado (reserva do possível), quando em jogo a dignidade da pessoa humana."
    ],
    "pontosChave": [
      "Direitos sociais são de segunda geração: exigem prestação positiva do Estado (fazer), diferente dos individuais (não fazer).",
      "Art. 6º lista educação, saúde, alimentação, trabalho, moradia, transporte, lazer, segurança, previdência, proteção à maternidade/infância, assistência aos desamparados.",
      "Mínimo existencial é exigível mesmo diante da reserva do possível, quando em jogo a dignidade da pessoa humana."
    ],
