        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Direitos sociais\", a ideia principal é: Direitos sociais são direitos fundamentais de segunda geração (ou dimensão): diferente dos direitos individuais de primeira geração, que exigem abstenção do Estado (não fazer), os direitos sociais exigem uma prestação positiva do Estado (fazer) — políticas públicas, serviços, estruturas que garantam condições mínimas de vida digna. Para estudar sem travar, guarde primeiro estas palavras-chave: direitos sociais, segunda geração, mínimo existencial. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: Direitos sociais exigem prestação positiva do Estado; o mínimo existencial é exigível mesmo diante da reserva do possível.",
