    "corpo": [
      "Direitos políticos são o conjunto de normas que regulam a participação do cidadão na vida política do Estado, essencialmente por meio do voto. O alistamento eleitoral e o voto são obrigatórios para os maiores de 18 anos e facultativos para analfabetos, maiores de 70 anos, e maiores de 16 e menores de 18 anos. São inalistáveis os estrangeiros e, durante o período do serviço militar obrigatório, os conscritos.",
      "Condições de elegibilidade incluem: nacionalidade brasileira, pleno exercício dos direitos políticos, alistamento eleitoral, domicílio eleitoral na circunscrição, filiação partidária e idade mínima (que varia conforme o cargo: 18 anos para vereador; 21 para deputado, prefeito e vice-prefeito; 30 para governador e vice; 35 para presidente, vice-presidente e senador).",
      "Diferente da inelegibilidade (impedimento a se candidatar, por não preencher requisito ou incidir em causa específica, como a Lei da Ficha Limpa), a perda e a suspensão de direitos políticos referem-se à privação, total ou temporária, do exercício desses direitos por quem já os detinha. Hipóteses: cancelamento da naturalização por sentença transitada em julgado (perda), incapacidade civil absoluta (suspensão), condenação criminal transitada em julgado enquanto durarem seus efeitos (suspensão), recusa de cumprir obrigação a todos imposta ou prestação alternativa (perda), e improbidade administrativa (suspensão, nos termos e prazo fixados em lei)."
    ],
