        "respostaEsperada": "Imagine como aprender as regras de um jogo sério: primeiro você entende quem pode agir, quando pode agir e qual consequência acontece. Neste capítulo, \"Organização do Estado e Administração Pública (art. 37)\", a ideia principal é: O art. 37 da Constituição estabelece os princípios expressos que regem toda a Administração Pública direta e indireta, de qualquer dos Poderes, em qualquer esfera federativa: legalidade, impessoalidade, moralidade, publicidade e eficiência — memorizados pelo mnemônico LIMPE. Para estudar sem travar, guarde primeiro estas palavras-chave: LIMPE, concurso público, improbidade administrativa. Depois responda: o que a banca quer que eu reconheça? A frase de memória é: LIMPE são os princípios expressos do art. 37 — e cargo efetivo sempre exige concurso público, salvo exceções constitucionais específicas.",
