    "corpo": [
      "O art. 144 da Constituição é o dispositivo mais diretamente ligado à carreira policial militar — define a segurança pública como dever do Estado, direito e responsabilidade de todos, exercida para a preservação da ordem pública e da incolumidade das pessoas e do patrimônio, por meio dos seguintes órgãos: Polícia Federal, Polícia Rodoviária Federal, Polícia Ferroviária Federal, Polícias Civis, Polícias Militares e Corpos de Bombeiros Militares, e Polícias Penais federal, estaduais e distrital.",
      "A Polícia Militar tem competência constitucional de polícia ostensiva e de preservação da ordem pública — atua de forma preventiva, visível, para evitar a ocorrência do ilícito. A Polícia Civil, dirigida por delegados de carreira, exerce as funções de polícia judiciária e a apuração de infrações penais, exceto as militares, cabendo-lhe a investigação (inquérito policial). Essa divisão de funções entre PM (ostensiva/preventiva) e PC (investigativa/repressiva) é conhecida como 'ciclo de polícia' incompleto ou bipartido — diferente de outros países, onde a mesma corporação acumula as duas funções (ciclo completo).",
      "Os Corpos de Bombeiros Militares, além das atribuições de defesa civil, exercem também atividades de polícia judiciária militar (nos crimes militares, quando organizados como força auxiliar e reserva do Exército). As Guardas Municipais, criadas por lei municipal, destinam-se à proteção de bens, serviços e instalações do Município, conforme dispuser a lei — e, desde a Lei 13.022/2014, também podem exercer poder de polícia administrativa e atuar na preservação da ordem pública em apoio, respeitadas as competências dos demais órgãos."
    ],
